PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,cnpj TEXT,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS companies(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,cnpj TEXT,status TEXT NOT NULL DEFAULT 'ACTIVE',email TEXT,phone TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT,name TEXT NOT NULL,email TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('OWNER','ACCOUNTANT','STAFF','CLIENT')),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(company_id) REFERENCES companies(id),UNIQUE(tenant_id,email));
CREATE TABLE IF NOT EXISTS account_plans(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'DRAFT',source_file TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,plan_id TEXT NOT NULL,source_id TEXT,account_code TEXT NOT NULL,classification_code TEXT,account_type TEXT NOT NULL CHECK(account_type IN('S','A')),description TEXT NOT NULL,parent_code TEXT,level INTEGER NOT NULL DEFAULT 0,is_postable INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,raw_data TEXT,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(plan_id) REFERENCES account_plans(id));
CREATE INDEX IF NOT EXISTS idx_accounts_tenant_plan ON accounts(tenant_id,plan_id);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('EXPENSE','REVENUE','BOTH')),account_id TEXT,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(company_id) REFERENCES companies(id),FOREIGN KEY(account_id) REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS banks(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT,name TEXT NOT NULL,account_id TEXT,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(company_id) REFERENCES companies(id),FOREIGN KEY(account_id) REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS accounting_rules(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT,name TEXT NOT NULL,priority INTEGER NOT NULL DEFAULT 100,active INTEGER NOT NULL DEFAULT 1,conditions_json TEXT NOT NULL DEFAULT '{}',debit_account_id TEXT,credit_account_id TEXT,settlement_account_id TEXT,confidence REAL NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS expenses(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,occurred_on TEXT NOT NULL,description TEXT NOT NULL,amount_cents INTEGER NOT NULL,payment_method TEXT NOT NULL,bank_id TEXT,category_id TEXT,document_id TEXT,status TEXT NOT NULL DEFAULT 'PENDING',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS revenues(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,occurred_on TEXT NOT NULL,description TEXT NOT NULL,amount_cents INTEGER NOT NULL,receipt_method TEXT NOT NULL,bank_id TEXT,category_id TEXT,document_id TEXT,status TEXT NOT NULL DEFAULT 'PENDING',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,original_name TEXT NOT NULL,storage_path TEXT NOT NULL,mime_type TEXT,size_bytes INTEGER,sha256 TEXT,status TEXT NOT NULL DEFAULT 'ACTIVE',uploaded_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS entries(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,source_type TEXT,source_id TEXT,occurred_on TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'NEEDS_CLASSIFICATION',confidence REAL NOT NULL DEFAULT 0,generated_by TEXT,approved_by TEXT,approved_at TEXT,rejected_reason TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS entry_lines(id TEXT PRIMARY KEY,entry_id TEXT NOT NULL,account_id TEXT NOT NULL,side TEXT NOT NULL CHECK(side IN('D','C')),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),memo TEXT,FOREIGN KEY(entry_id) REFERENCES entries(id) ON DELETE CASCADE,FOREIGN KEY(account_id) REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,entry_id TEXT NOT NULL,action TEXT NOT NULL CHECK(action IN('APPROVE','REJECT')),reason TEXT,user_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(entry_id) REFERENCES entries(id));
CREATE TABLE IF NOT EXISTS pendencies(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,resolved_at TEXT,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS export_layouts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,system_key TEXT NOT NULL,name TEXT NOT NULL,version TEXT,config_json TEXT NOT NULL DEFAULT '{}',active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS exports(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,system_key TEXT NOT NULL,period_start TEXT,period_end TEXT,status TEXT NOT NULL DEFAULT 'GENERATED',file_path TEXT,checksum TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS export_items(id TEXT PRIMARY KEY,export_id TEXT NOT NULL,entry_id TEXT NOT NULL,FOREIGN KEY(export_id) REFERENCES exports(id) ON DELETE CASCADE,FOREIGN KEY(entry_id) REFERENCES entries(id));
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT,action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,before_json TEXT,after_json TEXT,ip TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT,type TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS import_jobs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,plan_id TEXT,source_file TEXT,source_type TEXT NOT NULL,status TEXT NOT NULL,total_rows INTEGER NOT NULL DEFAULT 0,imported_rows INTEGER NOT NULL DEFAULT 0,rejected_rows INTEGER NOT NULL DEFAULT 0,issues_json TEXT NOT NULL DEFAULT '[]',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS rule_runs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,rule_id TEXT,source_type TEXT,source_id TEXT,matched INTEGER NOT NULL DEFAULT 0,confidence REAL,explanation TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS entry_reclassifications(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,entry_id TEXT NOT NULL,account_id TEXT NOT NULL,side TEXT NOT NULL,amount_cents INTEGER NOT NULL,reason TEXT,user_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,created_by TEXT NOT NULL,type TEXT NOT NULL,title TEXT NOT NULL,description TEXT,priority TEXT NOT NULL DEFAULT 'NORMAL',status TEXT NOT NULL DEFAULT 'OPEN',assigned_to TEXT,resolution TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
